package core

import (
	"errors"
	"fmt"
	"strings"
)

// Typed IDs keep a task ID from being passed where a repo ID is expected.
// They are opaque strings generated by the database layer.
type (
	ProjectID   string
	RepoID      string
	WorktreeID  string
	TaskID      string
	ChangeSetID string
	ProposalID  string
	BuildID     string
	AuditID     string
)

// ErrInvalidID is returned for empty IDs or IDs with whitespace.
var ErrInvalidID = errors.New("invalid id")

func checkID(kind, id string) error {
	if id == "" || strings.ContainsAny(id, " \t\r\n/\\") {
		return fmt.Errorf("%s %q: %w", kind, id, ErrInvalidID)
	}
	return nil
}

// Validate reports whether the ID is well formed.
func (id ProjectID) Validate() error { return checkID("project id", string(id)) }

// Validate reports whether the ID is well formed.
func (id RepoID) Validate() error { return checkID("repo id", string(id)) }

// Validate reports whether the ID is well formed.
func (id WorktreeID) Validate() error { return checkID("worktree id", string(id)) }

// Validate reports whether the ID is well formed.
func (id TaskID) Validate() error { return checkID("task id", string(id)) }

// Validate reports whether the ID is well formed.
func (id ChangeSetID) Validate() error { return checkID("change set id", string(id)) }

// Validate reports whether the ID is well formed.
func (id ProposalID) Validate() error { return checkID("proposal id", string(id)) }

// Validate reports whether the ID is well formed.
func (id BuildID) Validate() error { return checkID("build id", string(id)) }
